"""08.11.2026: порядок и редкость карточек по популярности героя («сверху самые классные с самыми популярными персонажами, чем менее популярны — тем менее редкая»).
python tools/card_pop.py        — показать, что поменяется (бэкап текущих редкостей: art/rarity_backup_20261108.json)
python tools/card_pop.py --apply — записать редкость и pop в базу (Management API)
Порядок в списках = порядок сверху вниз в коллекции."""
import json, os, sys, urllib.request

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.stdout.reconfigure(encoding='utf-8')
LEGEND = ['Пеппа-Ретик', 'Королева Пеппа', 'Маша-Ретик', 'Коржик-Ретик', 'Король Коржик', 'Карамелька-Ретик', 'Королева Карамелька', 'Компот-Ретик', 'Гений Компот', 'Крош-Ретик', 'Чемпион Крош',
          'Нюша-Ретик', 'Принцесса Нюша', 'Ёжик-Ретик', 'Ёжик-Хранитель', 'Лунтик-Ретик', 'Джордж-Ретик', 'Рыцарь Джордж', 'Чебурашка-Ретик', 'Дружок-Ретик', 'Симка-Ретик', 'Нолик-Ретик', 'Золотой Ретик', 'Няня Тишина']
EPIC = ['Папа Свин-Ретик', 'Мама Свинка-Ретик', 'Супер Папа Свин', 'Мама Свинка-Босс', 'Медведь-Ретик', 'Гонщик-Ретик', 'Скай-Ретик', 'Мама-Ретик', 'Папа-Ретик', 'Супер-Мама', 'Супер-Папа', 'Сажик-Ретик',
        'Дедушка-Ретик', 'Бабушка-Ретик', 'Бараш-Ретик', 'Копатыч-Ретик', 'Капитан Копатыч', 'Лосяш-Ретик', 'Профессор Лосяш', 'Кар-Карыч-Ретик', 'Совунья-Ретик', 'Пин-Ретик', 'Кот Матроскин-Ретик', 'Крокодил Гена-Ретик',
        'Гена-Ретик', 'Роза-Ретик', 'Лиза-Ретик', 'Малыш-Ретик', 'Мила-Ретик', 'Кузя-Ретик', 'Вупсень-Ретик', 'Пупсень-Ретик', 'Файер-Ретик', 'Игрек-Ретик', 'ДимДимыч-Ретик', 'Верта-Ретик', 'Папус-Ретик',
        'Сьюзи Овечка-Ретик', 'Мама, которая не моргает', 'Другая Карамелька', 'Анти-Коржик', 'Анти-Карамелька', 'Ночной Ретик']
RARE = ['Малыш Сажик-Великан', 'Принцесса Сьюзи', 'Ракета Пина', 'Маршал-Ретик', 'Кеша-Ретик', 'Тучка-Ретик', 'Пёс Шарик-Ретик', 'Шапокляк-Ретик', 'Панда-Ретик', 'Розочка-Ретик',
        'Анти-Компот', 'Анти-Мама', 'Анти-Папа', 'Анти-Король', 'Биби-Ретик', 'Пандочка-Ретик', 'Робо-Нюша-Ретик', 'Заводная Нюша', 'Ненастоящий Бараш', 'Ненастоящий Кар-Карыч', 'Заводной Кар-Карыч', 'Застывшая Пандочка', 'Совунья в полночь',
        'Гоня-Ретик', 'Лапочка-Ретик', 'Пуговка-Ретик', 'Нудник-Ретик', 'Странный доктор', 'Странный парикмахер', 'Лишний котёнок', 'Дедушка, который знает заранее', 'Бабушка, приехавшая раньше', 'Повар Сластён', 'Странная учительница',
        'Педро Пони-Ретик', 'Ребекка Крольчиха-Ретик', 'Дэнни Пёс-Ретик', 'Зои Зебра-Ретик', 'Кэнди Кошка-Ретик', 'Мадам Газель-Ретик', 'Бабушка Свинка-Ретик', 'Дедушка Свин-Ретик', 'Плюшевый Тедди', 'Мистер Динозавр-Ретик', 'Странный Джордж', 'Ненастоящая Сьюзи', 'Ночной Папа Свин', 'Дедушка с другим голосом',
        'Тимоха-Ретик', 'Мама Барбоскина-Ретик', 'Папа Барбоскин-Ретик', 'Бабушка Барбоскиных-Ретик', 'Дедушка Барбоскин-Ретик', 'Странная Лиза', 'Роза, которая знает', 'Лишний Барбоскин',
        'Мася-Ретик', 'Шпуля-Ретик', 'Баба Капа-Ретик', 'Корней Корнеевич-Ретик', 'Генерал Шер-Ретик', 'Пчелёнок-Ретик', 'Кролик — хозяин города']
PLAN = {}
for rar, names, top in (('legend', LEGEND, 4000), ('epic', EPIC, 3000), ('rare', RARE, 2000)):
    for i, n in enumerate(names):
        PLAN[n] = (rar, top - i)

s = json.load(open(os.path.join(ROOT, 'secrets.local.json'), encoding='utf-8'))
r = urllib.request.Request('https://%s.supabase.co/rest/v1/cards?select=id,name,rarity,channel&active=eq.true' % s['supabase_ref'], headers={'apikey': s['supabase_service_role'], 'Authorization': 'Bearer ' + s['supabase_service_role']})
cards = json.load(urllib.request.urlopen(r, timeout=30))
bak = os.path.join(ROOT, 'art', 'rarity_backup_20261108.json')
if not os.path.exists(bak):
    json.dump({c['id']: c['rarity'] for c in cards}, open(bak, 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
missing = [n for n in PLAN if n not in {c['name'] for c in cards}]
rows, changed, cnt = [], 0, {}
for i, c in enumerate(sorted(cards, key=lambda c: c['name'])):
    rar, pop = PLAN.get(c['name'], ('common', 1000 - i))        # всё, чего нет в списках, — свои монстры и предметы: обычные, внизу
    rows.append((c['id'], rar, pop)); changed += rar != c['rarity']; cnt[rar] = cnt.get(rar, 0) + 1
print('карточек', len(cards), 'поменяется редкость', changed, cnt, '| нет в базе:', missing)
if '--apply' in sys.argv:
    vals = ','.join("('%s','%s',%d)" % (i.replace("'", "''"), a, p) for i, a, p in rows)
    q = "alter table cards add column if not exists pop int not null default 0; update cards c set rarity = v.r, pop = v.p from (values %s) as v(id, r, p) where c.id = v.id;" % vals
    req = urllib.request.Request('https://api.supabase.com/v1/projects/%s/database/query' % s['supabase_ref'], json.dumps({'query': q}).encode(),
                                 {'Authorization': 'Bearer ' + s['supabase_pat'], 'Content-Type': 'application/json', 'User-Agent': 'multoretik-tools'})
    print('база:', urllib.request.urlopen(req, timeout=60).status)
